"""Statistics on Kaggle: every committed analysis script, run on Kaggle outputs.

The scripts (analysis_v3/*.py, kaggle/v4_search/search.py) are embedded verbatim by
make_kernel.py (sha256 printed). LINKS lays the attached kernel outputs / dataset files out
in the repo layout the scripts expect (file-by-file symlinks; several kernels may fill one
folder, e.g. the 3 v3b seeds -> results/v3b/merged). STEPS are the original command lines,
each run as a subprocess from its original folder; stdout goes to results/logs/<name>.txt.
Every file a step writes (not an input link) is copied to /kaggle/working/results.
"""
import hashlib
import os
import shutil
import subprocess
import sys
from pathlib import Path

EMBEDDED = {'analysis_v3/whowhen.py': '"""Shared statistics for the v3 analysis (Phase 1 and Phase 1b of PLAN_accuracy.md).\n\n* fast quadratic weighted kappa (numpy; identical to sklearn\'s, checked in __main__)\n* who/when decomposition: between-person vs within-person agreement\n* person-level bootstrap CIs (resample PERSONS, keep all their windows)\n* matched-pair factorial contrasts with Wilcoxon + Holm correction\n\nA run directory holds <config>/seed<k>/oof.json files with\noof = {y, pred, subject}. DIPSER subjects are student-sessions\n("group/experiment/subject"); the person is "group/subject". Other datasets\'\nsubject ids are used as persons directly.\n"""\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nfrom scipy.stats import wilcoxon\n\nN_CLASSES_MAX = 4\n\n\ndef person_of(subject):\n    parts = str(subject).split("/")\n    return f"{parts[0]}/{parts[2]}" if len(parts) == 3 else str(subject)\n\n\ndef qwk(y, p, k=None):\n    """Quadratic weighted kappa; 0 when undefined (constant predictions/labels)."""\n    y = np.asarray(y, dtype=int)\n    p = np.asarray(p, dtype=int)\n    k = k or max(int(y.max()), int(p.max())) + 1\n    observed = np.zeros((k, k))\n    np.add.at(observed, (y, p), 1)\n    n = observed.sum()\n    expected = np.outer(observed.sum(1), observed.sum(0)) / n\n    i, j = np.indices((k, k))\n    weights = (i - j) ** 2 / (k - 1) ** 2\n    denominator = (weights * expected).sum()\n    if denominator == 0:\n        return 0.0\n    return float(1 - (weights * observed).sum() / denominator)\n\n\ndef _corr(a, b):\n    if a.std() < 1e-12 or b.std() < 1e-12:\n        return 0.0\n    return float(np.corrcoef(a, b)[0, 1])\n\n\ndef decompose(y, p, groups):\n    """(between_r, within_r): agreement of per-group means, and after removing them."""\n    y = np.asarray(y, float)\n    p = np.asarray(p, float)\n    groups = np.asarray(groups).astype(str)\n    uniq, inverse = np.unique(groups, return_inverse=True)\n    counts = np.bincount(inverse)\n    mean_y = np.bincount(inverse, y) / counts\n    mean_p = np.bincount(inverse, p) / counts\n    return _corr(mean_y, mean_p), _corr(y - mean_y[inverse], p - mean_p[inverse])\n\n\ndef label_between_share(y, groups):\n    """Share of label variance explained by group (person/session) means."""\n    y = np.asarray(y, float)\n    _, inverse = np.unique(np.asarray(groups).astype(str), return_inverse=True)\n    means = np.bincount(inverse, y) / np.bincount(inverse)\n    return float(np.var(means[inverse]) / np.var(y)) if np.var(y) > 0 else 0.0\n\n\ndef balanced_accuracy(y, p):\n    y, p = np.asarray(y), np.asarray(p)\n    recalls = [float((p[y == k] == k).mean()) for k in np.unique(y)]\n    return float(np.mean(recalls))\n\n\ndef load_runs(run_dir):\n    """{config: [oof dict per seed]} for every <config>/seed*/oof.json under run_dir."""\n    runs = {}\n    for cfg_dir in sorted(Path(run_dir).iterdir()):\n        if not cfg_dir.is_dir():\n            continue\n        seeds = []\n        for f in sorted(cfg_dir.glob("seed*/oof.json")):\n            o = json.loads(f.read_text())["oof"]\n            seeds.append({"y": np.asarray(o["y"], int), "pred": np.asarray(o["pred"], int),\n                          "subject": np.asarray(o["subject"]).astype(str),\n                          "person": np.array([person_of(s) for s in o["subject"]])})\n        if seeds:\n            runs[cfg_dir.name] = seeds\n    return runs\n\n\ndef summarise(seeds):\n    """Seed-mean metrics of one configuration (who/when split by person)."""\n    q = [qwk(s["y"], s["pred"]) for s in seeds]\n    dec = [decompose(s["y"], s["pred"], s["person"]) for s in seeds]\n    ba = [balanced_accuracy(s["y"], s["pred"]) for s in seeds]\n    return {"qwk": float(np.mean(q)), "qwk_sd": float(np.std(q, ddof=1)) if len(q) > 1 else 0.0,\n            "per_seed": q, "between": float(np.mean([d[0] for d in dec])),\n            "within": float(np.mean([d[1] for d in dec])), "bacc": float(np.mean(ba))}\n\n\ndef person_bootstrap(seeds_a, seeds_b=None, n_boot=1000, seed=0):\n    """95% CI of the seed-mean QWK and within-person r, resampling persons.\n\n    With ``seeds_b`` it bootstraps the paired DIFFERENCE a - b of seed-mean QWK\n    (both configs are scored on the same resampled persons).\n    Returns {"qwk": (lo, hi), "within": (lo, hi)} or {"diff": (lo, hi)}.\n    """\n    rng = np.random.default_rng(seed)\n    persons = np.unique(seeds_a[0]["person"])\n    index = [{p: np.flatnonzero(s["person"] == p) for p in persons} for s in seeds_a]\n    index_b = ([{p: np.flatnonzero(s["person"] == p) for p in persons} for s in seeds_b]\n               if seeds_b else None)\n    q_draws, w_draws, d_draws = [], [], []\n    for _ in range(n_boot):\n        sample = rng.choice(persons, size=len(persons), replace=True)\n        qa, wa, qb = [], [], []\n        for k, s in enumerate(seeds_a):\n            rows = np.concatenate([index[k][p] for p in sample])\n            # duplicated persons must stay distinct groups for the within split\n            tags = np.concatenate([np.full(len(index[k][p]), j) for j, p in enumerate(sample)])\n            qa.append(qwk(s["y"][rows], s["pred"][rows]))\n            wa.append(decompose(s["y"][rows], s["pred"][rows], tags)[1])\n            if index_b:\n                sb = seeds_b[k]\n                rows_b = np.concatenate([index_b[k][p] for p in sample])\n                qb.append(qwk(sb["y"][rows_b], sb["pred"][rows_b]))\n        q_draws.append(np.mean(qa))\n        w_draws.append(np.mean(wa))\n        if index_b:\n            d_draws.append(np.mean(qa) - np.mean(qb))\n    ci = lambda x: (float(np.percentile(x, 2.5)), float(np.percentile(x, 97.5)))\n    if index_b:\n        return {"diff": ci(d_draws)}\n    return {"qwk": ci(q_draws), "within": ci(w_draws)}\n\n\ndef _pairs(names, factor):\n    """Matched pairs (a, b) of fusion configs that differ only in ``factor``."""\n    def parse(name):\n        parts = name.split("_")\n        loss = parts[3] if len(parts) > 3 else "coral"\n        return {"fusion": parts[0], "skip": parts[1], "drop": parts[2], "loss": loss}\n\n    def build(cfg):\n        base = f"{cfg[\'fusion\']}_{cfg[\'skip\']}_{cfg[\'drop\']}"\n        return base if cfg["loss"] == "coral" else f"{base}_{cfg[\'loss\']}"\n\n    fusion = [n for n in names if n.startswith(("gate_", "core_"))]\n    levels = {"link": ("skip", "skip1", "skip0"), "gate_vs_core": ("fusion", "gate", "core"),\n              "dropout": ("drop", "drop1", "drop0"), "soft_vs_coral": ("loss", "soft", "coral"),\n              "soft_vs_hybrid": ("loss", "soft", "hybrid")}\n    key, level_a, level_b = levels[factor]\n    pairs = []\n    for name in fusion:\n        cfg = parse(name)\n        if cfg[key] != level_a:\n            continue\n        other = dict(cfg)\n        other[key] = level_b\n        if build(other) in names:\n            pairs.append((name, build(other)))\n    return pairs\n\n\ndef contrasts(summary, factors=("link", "gate_vs_core", "dropout", "soft_vs_coral", "soft_vs_hybrid")):\n    """Wilcoxon on config-level mean QWK differences per factor, Holm-corrected."""\n    rows = []\n    for factor in factors:\n        pairs = _pairs(set(summary), factor)\n        if len(pairs) < 2:\n            continue\n        diffs = np.array([summary[a]["qwk"] - summary[b]["qwk"] for a, b in pairs])\n        p = 1.0 if np.allclose(diffs, 0) else float(wilcoxon(diffs).pvalue)\n        rows.append({"factor": factor, "pairs": len(pairs), "wins": int((diffs > 0).sum()),\n                     "median": float(np.median(diffs)), "p": p})\n    order = np.argsort([r["p"] for r in rows])\n    m, running = len(rows), 0.0\n    for rank, i in enumerate(order):\n        running = max(running, min(1.0, (m - rank) * rows[i]["p"]))\n        rows[i]["p_holm"] = running\n    return rows\n\n\nif __name__ == "__main__":\n    from sklearn.metrics import cohen_kappa_score\n    rng = np.random.default_rng(1)\n    for _ in range(200):\n        y, p = rng.integers(0, 3, 300), rng.integers(0, 3, 300)\n        assert abs(qwk(y, p) - cohen_kappa_score(y, p, weights="quadratic")) < 1e-9\n    print("qwk matches sklearn on 200 random cases")\n', 'analysis_v3/label_prior.py': '"""Label-only reference: variance shares and the leave-person-out experiment prior.\nUsage: python analysis_v3/label_prior.py corpus_full.npz   (no model, no features)."""\nimport numpy as np, sys\ndef k(a,b,weights=None,n=3):\n    O=np.zeros((n,n))\n    for i,j in zip(a,b): O[i,j]+=1\n    W=np.array([[(i-j)**2 for j in range(n)] for i in range(n)])/(n-1)**2\n    E=np.outer(O.sum(1),O.sum(0))/O.sum(); return 1-(W*O).sum()/(W*E).sum()\nd=np.load(sys.argv[1]); y=d[\'y\'].astype(float); s=d[\'subjects\']\ngrp=np.array([x.split(\'/\')[0] for x in s]); exp=np.array([x.split(\'/\')[1] for x in s])\nper=np.array([x.split(\'/\')[0]+\'/\'+x.split(\'/\')[2] for x in s]); ge=np.char.add(np.char.add(grp,\'/\'),exp)\ndef share(lab):\n    m={u:y[lab==u].mean() for u in np.unique(lab)}; mu=np.array([m[u] for u in lab]); return ((mu-y.mean())**2).sum()/((y-y.mean())**2).sum()\nprint(\'label-variance share: person %.2f | experiment(group-exp) %.2f | experiment index %.2f | session %.2f\'%(share(per),share(ge),share(exp),share(s)))\n# leave-person-out experiment prior: predict mean label of OTHER persons in same group/experiment\npred=np.empty_like(y)\nfor u in np.unique(ge):\n    idx=np.where(ge==u)[0]\n    for p in np.unique(per[idx]):\n        a=idx[per[idx]==p]; b=idx[per[idx]!=p]; pred[a]=y[b].mean()\n# map continuous prior to classes via thresholds matching marginal distribution\ncut=np.quantile(pred,[ (y==0).mean(), (y<=1).mean()]); pc=np.digitize(pred,cut,right=True)\nprint(\'experiment-prior (leave-person-out) QWK %.3f  pearson r %.3f\'%(k(y.astype(int),pc,weights=\'quadratic\'),np.corrcoef(pred,y)[0,1]))\n# within-session label variability\nw=[y[s==u].std() for u in np.unique(s)]; print(\'mean within-session label s.d. %.3f; sessions with constant label %d/%d\'%(np.mean(w),sum(np.array(w)==0),len(w)))\n\n# --- class-moment prior: mean label of the OTHER students at the same 4 s moment of the same class\nt=np.array([float(x.split(\'#\')[1]) for x in d[\'keys\']])\nt0={u:t[ge==u].min() for u in np.unique(ge)}\nslot=np.array([int(round((t[i]-t0[ge[i]])/4.0)) for i in range(len(t))])\ncm=np.char.add(np.char.add(ge,\'#\'),slot.astype(str))\nfrom collections import defaultdict\nS=defaultdict(float); N=defaultdict(int)\nfor c,v in zip(cm,y): S[c]+=v; N[c]+=1\nok=np.array([N[c]>1 for c in cm]); pm=np.array([(S[c]-v)/(N[c]-1) if N[c]>1 else np.nan for c,v in zip(cm,y)])\ncut=np.quantile(pm[ok],[(y[ok]==0).mean(),(y[ok]<=1).mean()]); pc=np.digitize(pm[ok],cut,right=True)\nprint(\'class-moment prior (other students, same moment) QWK %.3f  r %.3f  n=%d\'%(k(y[ok].astype(int),pc),np.corrcoef(pm[ok],y[ok])[0,1],ok.sum()))\nprint(\'label-variance share: class-moment %.2f\'%share(cm))\n', 'analysis_v3/split_leakage.py': '"""Random stratified split vs person-grouped split, same model (leakage diagnostic).\n\n    V4_MODELS=mlp V4_CORPUS=<corpus_full.npz> python split_leakage.py\nUses the best accuracy-tuned setting of results/v4/dipser_acc with its fixed epoch count,\nso neither scheme early-stops on its test fold. 5 folds each, seed 0, all complete windows.\n"""\nimport importlib.util\nimport json\nimport os\nfrom pathlib import Path\n\nimport numpy as np\nfrom sklearn.model_selection import StratifiedGroupKFold, StratifiedKFold\n\nROOT = Path(__file__).resolve().parent.parent\nos.environ.setdefault("V4_DATASET", "dipser")\nspec = importlib.util.spec_from_file_location("s", ROOT / "kaggle/v4_search/search.py")\nS = importlib.util.module_from_spec(spec)\nspec.loader.exec_module(S)\n\nfinal = json.loads((ROOT / "results/v4/dipser_acc/final.json").read_text())\nimport optuna\np = S.suggest(optuna.trial.FixedTrial(final["best_params"]))\nepochs = max(1, final["final_epochs"] or 10)\nc, k, _ = S.load()\nS.set_orders(c)   # search.py >= da9f8fb reads the stored orders (paper corpus: 16 x 6, as before)\ny, persons = c["y"], c["persons"]\nX = S.features(c, p, np.arange(len(y)))\nschemes = {"random stratified (windows)": StratifiedKFold(5, shuffle=True, random_state=0).split(y, y),\n           "person-grouped stratified": StratifiedGroupKFold(5, shuffle=True, random_state=0).split(y, y, persons)}\nout = {"params": p, "epochs": epochs, "n": int(len(y)), "persons": int(len(np.unique(persons)))}\nfor name, folds in schemes.items():\n    rows = []\n    for tr, te in folds:\n        pred, _ = S.fit_mlp(p, [x[tr] for x in X], y[tr], [x[te] for x in X], y[te], k, 0,\n                            epochs=epochs)\n        rows.append(S.scores(y[te], pred, k))\n        shared = len(set(persons[tr]) & set(persons[te]))\n        print(f"{name}: acc {rows[-1][\'acc\']:.4f} qwk {rows[-1][\'qwk\']:+.4f} "\n              f"(test persons also in train: {shared}/{len(set(persons[te]))})", flush=True)\n    out[name] = {m: [float(np.mean([r[m] for r in rows])), float(np.std([r[m] for r in rows]))]\n                 for m in ("acc", "qwk", "balanced_acc")}\n    out[name]["recall"] = np.mean([r["recall"] for r in rows], axis=0).round(3).tolist()\n    out[name]["majority_acc"] = float(np.mean(y == np.bincount(y).argmax()))\nprint(json.dumps({k: v for k, v in out.items() if k not in ("params",)}, indent=1))\n(ROOT / "results/v4/split_leakage.json").write_text(json.dumps(out, indent=1))\n', 'analysis_v3/compare_v3.py': '"""Who/when report and Gate 1 verdict for any set of gTAO runs.\n\n    python compare_v3.py --run "v2=<dir>" --run "v3 fold=<dir>" ... [--gate] [--boot 1000]\n\nEach <dir> holds <config>/seed<k>/oof.json. Per run it prints:\n* label variance between persons (how "trait-like" the labels are);\n* per config: QWK mean ± s.d., between-person r, within-person r, balanced accuracy;\n* person-bootstrap 95% CIs for every single stream, the best fusion and the shuffle\n  control, plus the paired CI of (best fusion - best single);\n* factorial contrasts, Wilcoxon on config means, Holm-corrected;\n* with --gate: the Gate 1 verdict as amended in PLAN_accuracy.md (2026-11-17,\n  fixed before any v3 output was seen).\n"""\nimport argparse\nimport json\n\nimport numpy as np\n\nfrom whowhen import contrasts, label_between_share, load_runs, person_bootstrap, summarise\n\nSTREAMS = ("face", "facemesh", "head_pose", "physio")\n\n\ndef best_of(summary, prefix_filter):\n    items = [(c, s) for c, s in summary.items() if prefix_filter(c)]\n    return max(items, key=lambda kv: kv[1]["qwk"]) if items else (None, None)\n\n\ndef report(name, runs, n_boot, gate):\n    summary = {c: summarise(seeds) for c, seeds in runs.items()}\n    first = next(iter(runs.values()))[0]\n    persons = len(np.unique(first["person"]))\n    share_person = label_between_share(first["y"], first["person"])\n    share_session = label_between_share(first["y"], first["subject"])\n    print(f"\\n{\'=\' * 100}\\n{name}: {len(first[\'y\'])} windows, {persons} persons | label variance "\n          f"between persons {share_person:.0%} (between sessions {share_session:.0%})")\n    print(f"{\'config\':28s} {\'QWK\':>15s} {\'between\':>8s} {\'within\':>8s} {\'bal.acc\':>8s}")\n    order = sorted(summary, key=lambda c: (not c.startswith("unimodal"), -summary[c]["qwk"]))\n    for c in order:\n        s = summary[c]\n        print(f"{c:28s} {s[\'qwk\']:+.3f} ± {s[\'qwk_sd\']:.3f} {s[\'between\']:+8.2f} "\n              f"{s[\'within\']:+8.2f} {s[\'bacc\']:8.3f}")\n\n    singles = [c for c in summary if c.startswith("unimodal")]\n    fusions = [c for c in summary if c.startswith(("gate_", "core_"))]\n    best_single, _ = best_of(summary, lambda c: c in singles)\n    best_fusion, _ = best_of(summary, lambda c: c in fusions)\n    ci = {}\n    targets = singles + [c for c in (best_fusion, "shuffle_core_skip1_drop1") if c in summary]\n    print(f"\\nperson-bootstrap 95% CI ({n_boot} draws, persons resampled):")\n    for c in targets:\n        ci[c] = person_bootstrap(runs[c], n_boot=n_boot)\n        print(f"  {c:28s} QWK [{ci[c][\'qwk\'][0]:+.3f}, {ci[c][\'qwk\'][1]:+.3f}]   "\n              f"within r [{ci[c][\'within\'][0]:+.3f}, {ci[c][\'within\'][1]:+.3f}]")\n    if best_single and best_fusion:\n        diff = person_bootstrap(runs[best_fusion], runs[best_single], n_boot=n_boot)["diff"]\n        above = sum(summary[c]["qwk"] > summary[best_single]["qwk"] for c in fusions)\n        print(f"  best fusion {best_fusion} - best single {best_single}: "\n              f"{summary[best_fusion][\'qwk\'] - summary[best_single][\'qwk\']:+.3f} "\n              f"CI [{diff[0]:+.3f}, {diff[1]:+.3f}] | fusions above best single: {above}/{len(fusions)}")\n\n    rows = contrasts(summary)\n    if rows:\n        print("\\ncontrasts (config-level Wilcoxon, Holm across factors):")\n        for r in rows:\n            print(f"  {r[\'factor\']:15s} wins {r[\'wins\']}/{r[\'pairs\']}  median {r[\'median\']:+.3f}  "\n                  f"p {r[\'p\']:.4f}  p_holm {r[\'p_holm\']:.4f}")\n\n    result = {"summary": summary, "ci": ci, "contrasts": rows}\n    if gate:\n        def best_stream(stream):\n            cands = [c for c in singles if c.startswith(f"unimodal_{stream}_")]\n            return max(cands, key=lambda c: summary[c]["qwk"]) if cands else None\n        recovered = []\n        for stream in ("face", "head_pose", "physio"):\n            c = best_stream(stream)\n            if c and summary[c]["qwk"] >= 0.10:\n                lo = (ci.get(c) or person_bootstrap(runs[c], n_boot=n_boot))["qwk"][0]\n                if lo > 0:\n                    recovered.append(stream)\n        within_ok = [c for c in singles if summary[c]["within"] >= 0.10]\n        print(f"\\nGATE 1 ({name}): (a) recovered with CI>0: {recovered or \'none\'} -> "\n              f"{\'PASS\' if len(recovered) >= 2 else \'FAIL\'} | (b) streams with within r >= 0.10: "\n              f"{within_ok or \'none\'} -> {\'PASS\' if within_ok else \'FAIL\'}")\n        result["gate"] = {"a_recovered": recovered, "b_within": within_ok}\n    return result\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])\n    ap.add_argument("--run", action="append", required=True, help="NAME=DIR")\n    ap.add_argument("--boot", type=int, default=1000)\n    ap.add_argument("--gate", action="store_true")\n    ap.add_argument("--json", default=None, help="write all results to this file")\n    args = ap.parse_args()\n    out = {}\n    for item in args.run:\n        name, path = item.split("=", 1)\n        out[name] = report(name, load_runs(path), args.boot, args.gate)\n    if args.json:\n        with open(args.json, "w") as handle:\n            json.dump(out, handle, indent=1, default=float)\n\n\nif __name__ == "__main__":\n    main()\n', 'analysis_v3/phase1b.py': '"""Phase 1b (exploratory, post hoc): who-vs-when decomposition across runs and datasets.\n\n    cd analysis_v3 && python phase1b.py [--corpus <corpus_full.npz>]\n\nFor every run: share of label variance between persons, and for the best config of each\nsingle stream and the best fusion: QWK, between-person r (per-person mean prediction vs\nmean label: does the model rank STUDENTS?) and within-person r (after removing each\nperson\'s means: does it follow changes WITHIN a student?).\nWrites ../results/phase1b/whowhen.json and ../paper/figures/fig_whowhen.pdf (+ .png).\nWith --corpus it also adds the label-only decomposition of the full DIPSER corpus.\n"""\nimport argparse\nimport json\nfrom pathlib import Path\n\nimport numpy as np\n\nfrom whowhen import label_between_share, load_runs, summarise\n\nROOT = Path(__file__).resolve().parent.parent\nRUNS = [\n    ("DIPSER v2 (paper slice, session folds)", ROOT / "results/v2/raw_dipser/gtao_grid_v1"),\n    ("DIPSER v3 fold (person folds, z-score)", ROOT / "results/v3/gtao_grid_v3_fold_person_strat"),\n    ("DIPSER v3 subject (within-session z-score)", ROOT / "results/v3/gtao_grid_v3_subject_person_strat"),\n    ("DAiSEE (group k-fold)", ROOT / "results/v2/raw_daisee/daisee_gt_grid/P2_groupkfold"),\n    ("EngageNet (group k-fold)", ROOT / "results/v2/raw_engagenet/engagenet_gt_grid/P2_groupkfold"),\n]\nSTREAMS = ("face", "facemesh", "head_pose", "physio")\nLABELS = {"face": "Face", "facemesh": "Face mesh", "head_pose": "Head pose",\n          "physio": "Physiology", "fusion": "Best fusion"}\nBLUE, ORANGE = "#2a78d6", "#eb6834"          # dataviz palette slots 1 and 2 (light)\nSHORT = {"paper slice, session folds": "slice, session folds",\n         "person folds, z-score": "person folds, z-score",\n         "within-session z-score": "session z-score",\n         "group k-fold": "group k-fold"}\nINK, MUTED, GRID = "#1f1f1e", "#6b6b68", "#e4e4e1"\n\n\ndef analyse(path):\n    runs = load_runs(path)\n    summary = {c: summarise(s) for c, s in runs.items() if not c.startswith("shuffle")}\n    first = next(iter(runs.values()))[0]\n    rows = {}\n    for stream in STREAMS:\n        cands = [c for c in summary if c.startswith(f"unimodal_{stream}")\n                 and not c.startswith("unimodal_facemesh" if stream == "face" else "~")]\n        if cands:\n            best = max(cands, key=lambda c: summary[c]["qwk"])\n            rows[stream] = {"config": best, **summary[best]}\n    fusions = [c for c in summary if c.startswith(("gate_", "core_"))]\n    if fusions:\n        best = max(fusions, key=lambda c: summary[c]["qwk"])\n        rows["fusion"] = {"config": best, **summary[best]}\n    return {"n_windows": int(len(first["y"])), "n_persons": int(len(np.unique(first["person"]))),\n            "label_between_person": label_between_share(first["y"], first["person"]),\n            "label_between_session": label_between_share(first["y"], first["subject"]),\n            "rows": rows}\n\n\ndef corpus_labels(path):\n    d = np.load(path, allow_pickle=False)\n    y = d["y"].astype(float)\n    sessions = d["subjects"].astype(str)\n    persons = np.array(["/".join([s.split("/")[0], s.split("/")[2]]) for s in sessions])\n    experiments = np.array(["/".join(s.split("/")[:2]) for s in sessions])\n    return {"n_windows": int(len(y)), "n_persons": int(len(np.unique(persons))),\n            "label_between_person": label_between_share(y, persons),\n            "label_between_experiment": label_between_share(y, experiments),\n            "label_between_session": label_between_share(y, sessions)}\n\n\ndef figure(results, out_pdf):\n    import matplotlib\n    matplotlib.use("Agg")\n    import matplotlib.pyplot as plt\n    plt.rcParams.update({"font.size": 8, "axes.edgecolor": MUTED, "axes.labelcolor": INK,\n                         "xtick.color": MUTED, "ytick.color": INK, "font.family": "sans-serif"})\n    names = list(results)\n    fig, axes = plt.subplots(1, len(names), figsize=(7.2, 2.5), sharex=True, sharey=True)\n    order = ["face", "facemesh", "head_pose", "physio", "fusion"]\n    for ax, name in zip(axes, names):\n        res = results[name]\n        for i, key in enumerate(order):\n            row = res["rows"].get(key)\n            ax.axhline(i, color=GRID, lw=0.6, zorder=0)\n            if row is None:\n                ax.text(0.5, i, "no sensor", ha="center", va="center", color=MUTED, fontsize=6.5)\n                continue\n            b, w = row["between"], row["within"]\n            ax.plot([w, b], [i, i], color=GRID, lw=2, zorder=1, solid_capstyle="round")\n            ax.scatter([b], [i], s=34, color=BLUE, edgecolor="white", linewidth=1, zorder=3)\n            ax.scatter([w], [i], s=34, color=ORANGE, edgecolor="white", linewidth=1, zorder=3)\n        ax.axvline(0, color=MUTED, lw=0.8, zorder=0)\n        title = name.split(" (")[0]\n        sub = name.split(" (")[1].rstrip(")") if " (" in name else ""\n        ax.set_title(f"{title}\\n{SHORT.get(sub, sub)}\\nlabels {res[\'label_between_person\']:.0%} between",\n                     fontsize=6.8, color=INK)\n        ax.set_xlim(-0.75, 1.0)\n        ax.set_xticks([-0.5, 0, 0.5, 1.0])\n        ax.set_xticklabels(["-.5", "0", ".5", "1"])\n        for side in ("top", "right", "left"):\n            ax.spines[side].set_visible(False)\n        ax.tick_params(axis="y", length=0)\n    axes[0].set_yticks(range(len(order)))\n    axes[0].set_yticklabels([LABELS[k] for k in order])\n    axes[0].invert_yaxis()\n    fig.supxlabel("Pearson r between prediction and label", fontsize=8, color=INK, y=0.03)\n    handles = [plt.Line2D([], [], marker="o", ls="", color=BLUE, markersize=6,\n                          label="Between persons (who)"),\n               plt.Line2D([], [], marker="o", ls="", color=ORANGE, markersize=6,\n                          label="Within persons (when)")]\n    fig.legend(handles=handles, loc="upper center", ncol=2, frameon=False, fontsize=8,\n               bbox_to_anchor=(0.5, 1.02))\n    fig.tight_layout(rect=(0, 0, 1, 0.92))\n    out_pdf.parent.mkdir(parents=True, exist_ok=True)\n    fig.savefig(out_pdf, bbox_inches="tight")\n    fig.savefig(out_pdf.with_suffix(".png"), dpi=200, bbox_inches="tight")\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])\n    ap.add_argument("--corpus", default=None)\n    args = ap.parse_args()\n    results = {name: analyse(path) for name, path in RUNS if path.is_dir()}\n    out = {"runs": results}\n    if args.corpus:\n        out["dipser_full_corpus_labels"] = corpus_labels(args.corpus)\n    for name, res in results.items():\n        print(f"\\n{name}: {res[\'n_windows\']} windows, {res[\'n_persons\']} persons, label "\n              f"between-person {res[\'label_between_person\']:.0%}, between-session "\n              f"{res[\'label_between_session\']:.0%}")\n        for key, row in res["rows"].items():\n            print(f"  {LABELS[key]:12s} {row[\'config\']:28s} QWK {row[\'qwk\']:+.3f}  "\n                  f"between {row[\'between\']:+.2f}  within {row[\'within\']:+.2f}")\n    if "dipser_full_corpus_labels" in out:\n        c = out["dipser_full_corpus_labels"]\n        print(f"\\nDIPSER full corpus (labels only): {c[\'n_windows\']} windows, {c[\'n_persons\']} "\n              f"persons; between person {c[\'label_between_person\']:.0%}, experiment "\n              f"{c[\'label_between_experiment\']:.0%}, session {c[\'label_between_session\']:.0%}")\n    dest = ROOT / "results/phase1b"\n    dest.mkdir(parents=True, exist_ok=True)\n    (dest / "whowhen.json").write_text(json.dumps(out, indent=1, default=float))\n    figure(results, ROOT / "paper/figures/fig_whowhen.pdf")\n\n\nif __name__ == "__main__":\n    main()\n', 'analysis_v3/gate3.py': '"""Gate 3 verdict for the v3b full-corpus run (PLAN_accuracy.md, Phase 3b).\n\n    python gate3.py --out <folder holding gtao_grid_v3b/, gtao_grid_v3b_arm_*/,\n                     gtao_grid_v3b_leo/> [--boot 2000] [--json gate3.json]\n\nWritten 2026-11-18, before any v3b output existed. It applies the pre-declared\ncriteria mechanically:\n (a) >= 2 of {face, head pose, physio}: best single-stream config QWK >= 0.10, person-\n     bootstrap CI lower bound > 0, and QWK minus its classmate control with CI > 0;\n (b) some single stream: within-SESSION r >= 0.10 with CI lower bound > 0;\n (c) best single stream: partial r(pred, label | R2) >= 0.10 with CI lower bound > 0\n     (best fusion reported beside it);\n (d) H4: best fusion - best single > 0 with CI lower bound > 0 and bootstrap p < 0.05;\n (e) per fix (no_phys / no_lag / no_ctx / no_calib arms): selected - reverted over the\n     8 single-stream configs; helps if Holm p < 0.05 (Wilcoxon over config x seed pairs)\n     and the person-bootstrap CI of the mean difference excludes 0.\nR2 = experiment prior: mean TRUE label of the windows of the other outer folds in the\nsame group/experiment (recomputed from each run\'s own folds).\n"""\nimport argparse\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nfrom scipy.stats import wilcoxon\n\nfrom whowhen import qwk\n\nSTREAMS = ("face", "facemesh", "head_pose", "physio")\nFIXES = ("no_phys", "no_lag", "no_ctx", "no_calib")\n\n\ndef person_of(session):\n    parts = str(session).split("/")\n    return f"{parts[0]}/{parts[2]}" if len(parts) == 3 else str(session)\n\n\ndef experiment_of(session):\n    return "/".join(str(session).split("/")[:2])\n\n\ndef experiment_prior(y_true, sessions, folds):\n    """Mean true label of other-fold windows in the same group/experiment."""\n    experiments = np.array([experiment_of(s) for s in sessions])\n    prior = np.full(len(y_true), np.nan)\n    for e in np.unique(experiments):\n        in_e = experiments == e\n        for f in np.unique(folds[in_e]):\n            train = in_e & (folds != f)\n            if train.any():\n                prior[in_e & (folds == f)] = y_true[train].mean()\n    prior[np.isnan(prior)] = np.nanmean(y_true)\n    return prior\n\n\ndef load_dir(run_dir):\n    """{config: [per-seed dict of arrays]} for one grid folder."""\n    runs = {}\n    run_dir = Path(run_dir)\n    if not run_dir.is_dir():\n        return runs\n    for f in sorted(run_dir.glob("*/seed*/oof.json")):\n        d = json.loads(f.read_text())\n        o = d["oof"]\n        rec = {k: np.asarray(o[k]) for k in ("keys", "y", "y_true", "pred", "subject", "fold")}\n        rec["person"] = np.array([person_of(s) for s in rec["subject"]])\n        rec["prior"] = experiment_prior(rec["y_true"].astype(float), rec["subject"], rec["fold"])\n        runs.setdefault(f.parent.parent.name, []).append(rec)\n    return runs\n\n\ndef _corr(a, b):\n    if len(a) < 3 or a.std() < 1e-12 or b.std() < 1e-12:\n        return 0.0\n    return float(np.corrcoef(a, b)[0, 1])\n\n\ndef metrics(rec, rows=None, tags=None):\n    """QWK, within-session r and partial r | R2 on rows (tags = session ids)."""\n    if rows is None:\n        rows = np.arange(len(rec["y"]))\n        tags = rec["subject"]\n    y = rec["y"][rows].astype(float)\n    p = rec["pred"][rows].astype(float)\n    out = {"qwk": qwk(rec["y"][rows].astype(int), rec["pred"][rows].astype(int))}\n    _, inverse = np.unique(tags, return_inverse=True)\n    counts = np.bincount(inverse)\n    y_dev = y - (np.bincount(inverse, weights=y) / counts)[inverse]\n    p_dev = p - (np.bincount(inverse, weights=p) / counts)[inverse]\n    out["within_session"] = _corr(y_dev, p_dev)\n    if rows is not None and len(rows) == len(rec["y"]) and tags is rec["subject"]:\n        _, pinv = np.unique(rec["person"], return_inverse=True)\n        pc = np.bincount(pinv)\n        out["within_person"] = _corr(y - (np.bincount(pinv, weights=y) / pc)[pinv],\n                                     p - (np.bincount(pinv, weights=p) / pc)[pinv])\n    prior = rec["prior"][rows]\n    design = np.column_stack([np.ones(len(prior)), prior])\n    resid = lambda v: v - design @ np.linalg.lstsq(design, v, rcond=None)[0]\n    out["partial_r"] = _corr(resid(y), resid(p))\n    return out\n\n\ndef seed_mean(recs, draw=None):\n    vals = []\n    for k, rec in enumerate(recs):\n        if draw is None:\n            vals.append(metrics(rec))\n        else:\n            rows, tags = draw[k]\n            vals.append(metrics(rec, rows, tags))\n    keys = set.intersection(*(set(v) for v in vals))\n    return {m: float(np.mean([v[m] for v in vals])) for m in sorted(keys)}\n\n\ndef make_draws(recs, persons_sample):\n    """Rows and session tags for one bootstrap draw, per seed (duplicates kept apart)."""\n    out = []\n    for rec in recs:\n        if "_by_person" not in rec:\n            rec["_by_person"] = {q: np.flatnonzero(rec["person"] == q)\n                                 for q in np.unique(rec["person"])}\n            _, rec["_session_id"] = np.unique(rec["subject"], return_inverse=True)\n        n_sessions = rec["_session_id"].max() + 1\n        rows, tags = [], []\n        for j, person in enumerate(persons_sample):\n            r = rec["_by_person"].get(person, np.zeros(0, dtype=int))\n            rows.append(r)\n            tags.append(rec["_session_id"][r] + j * n_sessions)\n        out.append((np.concatenate(rows), np.concatenate(tags)))\n    return out\n\n\ndef bootstrap(recs_a, recs_b=None, n_boot=2000, seed=0):\n    """Person bootstrap: CIs of each metric (or of the a - b QWK difference)."""\n    rng = np.random.default_rng(seed)\n    persons = np.unique(np.concatenate([r["person"] for r in recs_a]))\n    draws_a, draws_d = [], []\n    for _ in range(n_boot):\n        sample = rng.choice(persons, size=len(persons), replace=True)\n        ma = seed_mean(recs_a, make_draws(recs_a, sample))\n        draws_a.append(ma)\n        if recs_b is not None:\n            mb = seed_mean(recs_b, make_draws(recs_b, sample))\n            draws_d.append(ma["qwk"] - mb["qwk"])\n    ci = lambda x: (float(np.percentile(x, 2.5)), float(np.percentile(x, 97.5)))\n    result = {m: ci([d[m] for d in draws_a]) for m in draws_a[0]}\n    if recs_b is not None:\n        d = np.array(draws_d)\n        result["diff"] = ci(d)\n        result["diff_p"] = float(min(1.0, 2 * min((d <= 0).mean(), (d >= 0).mean())))\n    return result\n\n\ndef holm(pvalues):\n    order = np.argsort(pvalues)\n    adjusted = np.empty(len(pvalues))\n    running = 0.0\n    for rank, i in enumerate(order):\n        running = max(running, (len(pvalues) - rank) * pvalues[i])\n        adjusted[i] = min(1.0, running)\n    return adjusted.tolist()\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])\n    ap.add_argument("--out", required=True)\n    ap.add_argument("--boot", type=int, default=2000)\n    ap.add_argument("--json", default=None)\n    args = ap.parse_args()\n    root = Path(args.out)\n    main_runs = load_dir(root / "gtao_grid_v3b")\n    point = {c: seed_mean(r) for c, r in main_runs.items()}\n    print(f"{\'config\':34s} {\'QWK\':>7s} {\'within-s\':>9s} {\'partial\':>8s} seeds")\n    for c in sorted(point, key=lambda c: -point[c]["qwk"]):\n        print(f"{c:34s} {point[c][\'qwk\']:+7.3f} {point[c][\'within_session\']:+9.3f} "\n              f"{point[c][\'partial_r\']:+8.3f} {len(main_runs[c])}")\n\n    singles = [c for c in point if c.startswith("unimodal_")]\n    fusions = [c for c in point if c.startswith(("gate_", "core_"))]\n    best_stream = {s: max([c for c in singles if c.startswith(f"unimodal_{s}_")],\n                          key=lambda c: point[c]["qwk"]) for s in STREAMS\n                   if any(c.startswith(f"unimodal_{s}_") for c in singles)}\n    best_single = max(singles, key=lambda c: point[c]["qwk"])\n    best_fusion = max(fusions, key=lambda c: point[c]["qwk"])\n    ci = {c: bootstrap(main_runs[c], n_boot=args.boot) for c in set(best_stream.values())\n          | {best_fusion}}\n    result = {"point": point, "ci": ci, "best_stream": best_stream,\n              "best_single": best_single, "best_fusion": best_fusion}\n\n    # (a)\n    recovered = []\n    for s in ("face", "head_pose", "physio"):\n        c = best_stream.get(s)\n        mate = f"classmate_unimodal_{s}_cw"\n        if not c or mate not in main_runs:\n            continue\n        vs_mate = bootstrap(main_runs[c], main_runs[mate], n_boot=args.boot)\n        result.setdefault("vs_classmate", {})[s] = vs_mate\n        if point[c]["qwk"] >= 0.10 and ci[c]["qwk"][0] > 0 and vs_mate["diff"][0] > 0:\n            recovered.append(s)\n    # (b)\n    within_ok = [s for s, c in best_stream.items()\n                 if point[c]["within_session"] >= 0.10 and ci[c]["within_session"][0] > 0]\n    # (c)\n    c_ok = (point[best_single]["partial_r"] >= 0.10 and ci[best_single]["partial_r"][0] > 0)\n    # (d)\n    d = bootstrap(main_runs[best_fusion], main_runs[best_single], n_boot=args.boot)\n    above = sum(point[c]["qwk"] > point[best_single]["qwk"] for c in fusions)\n    h4_flip = d["diff"][0] > 0 and d["diff_p"] < 0.05\n    # (e)\n    fix_rows = []\n    for fix in FIXES:\n        arm = load_dir(root / f"gtao_grid_v3b_arm_{fix}")\n        if not arm:\n            fix_rows.append({"fix": fix, "status": "never selected (arm identical, not run)",\n                             "p": 1.0})\n            continue\n        pairs = []\n        for c in singles:\n            if c in arm:\n                for a, b in zip(main_runs[c], arm[c]):\n                    pairs.append(metrics(a)["qwk"] - metrics(b)["qwk"])\n        stat_p = float(wilcoxon(pairs).pvalue) if np.any(np.abs(pairs) > 0) else 1.0\n        fix_rows.append({"fix": fix, "mean_delta_qwk": float(np.mean(pairs)),\n                         "n_pairs": len(pairs), "p": stat_p})\n    for row, p_holm in zip(fix_rows, holm([r["p"] for r in fix_rows])):\n        row["p_holm"] = p_holm\n        row["helps"] = bool(p_holm < 0.05 and row.get("mean_delta_qwk", 0) > 0)\n    base = load_dir(root / "gtao_grid_v3b_arm_base")\n    if base:\n        result["all_fixes_vs_base"] = {c: seed_mean(main_runs[c])["qwk"] - seed_mean(base[c])["qwk"]\n                                       for c in singles if c in base}\n    leo = load_dir(root / "gtao_grid_v3b_leo")\n    result["leave_experiment_out"] = {c: seed_mean(r) for c, r in leo.items()}\n\n    gate = {"a_recovered": recovered, "a_pass": len(recovered) >= 2,\n            "b_streams": within_ok, "b_pass": bool(within_ok),\n            "c_best_single": {"config": best_single, "partial_r": point[best_single]["partial_r"],\n                              "ci": ci[best_single]["partial_r"]},\n            "c_best_fusion": {"config": best_fusion, "partial_r": point[best_fusion]["partial_r"],\n                              "ci": ci[best_fusion]["partial_r"]},\n            "c_pass": bool(c_ok),\n            "d_fusions_above_best_single": f"{above}/{len(fusions)}",\n            "d_diff": point[best_fusion]["qwk"] - point[best_single]["qwk"],\n            "d_ci": d["diff"], "d_p": d["diff_p"], "d_h4_flips": bool(h4_flip),\n            "e_fixes": fix_rows}\n    result["gate"] = gate\n    print("\\nGATE 3")\n    print(f" (a) recovered (QWK>=0.10, CI>0, > classmate): {recovered or \'none\'} -> "\n          f"{\'PASS\' if gate[\'a_pass\'] else \'FAIL\'}")\n    print(f" (b) within-session r >= 0.10, CI>0: {within_ok or \'none\'} -> "\n          f"{\'PASS\' if gate[\'b_pass\'] else \'FAIL\'}")\n    print(f" (c) partial r | R2, best single {best_single}: {point[best_single][\'partial_r\']:+.3f} "\n          f"CI [{ci[best_single][\'partial_r\'][0]:+.3f}, {ci[best_single][\'partial_r\'][1]:+.3f}] -> "\n          f"{\'PASS\' if c_ok else \'FAIL\'} (best fusion {point[best_fusion][\'partial_r\']:+.3f})")\n    print(f" (d) best fusion - best single {gate[\'d_diff\']:+.3f} CI [{d[\'diff\'][0]:+.3f}, "\n          f"{d[\'diff\'][1]:+.3f}] p {d[\'diff_p\']:.4f}; above: {gate[\'d_fusions_above_best_single\']}"\n          f" -> H4 {\'FLIPS\' if h4_flip else \'stays rejected\'}")\n    for r in fix_rows:\n        print(f" (e) {r[\'fix\']:9s} {r.get(\'mean_delta_qwk\', 0):+.3f} p_holm {r[\'p_holm\']:.4f} "\n              f"{\'HELPS\' if r[\'helps\'] else \'-\'} {r.get(\'status\', \'\')}")\n    if args.json:\n        Path(args.json).write_text(json.dumps(result, indent=1, default=float))\n\n\nif __name__ == "__main__":\n    main()\n', 'analysis_v3/rich_compare.py': '"""Paper vs rich Tchebichef features on the same fixed 13-person test split (v4 search).\n\nPaired person bootstrap (persons resampled, same draw for both runs), metrics averaged\nover the 3 final seeds. Also: what the search explored (best val per face_k / seq_t).\n"""\nimport json\nimport sys\nfrom pathlib import Path\n\nimport numpy as np\nfrom sklearn.metrics import accuracy_score, cohen_kappa_score\n\nR = Path(__file__).resolve().parent.parent / "results" / "v4"\n\n\ndef person_of(s):\n    """Same rule as kaggle/v4_search/search.py: group/subject (a student across experiments)."""\n    parts = str(s).split("/")\n    return f"{parts[0]}/{parts[2]}" if len(parts) == 3 else str(s)\n\n\ndef load(run):\n    seeds = [json.load(open(R / run / f"preds_test_seed{s}.json")) for s in range(3)]\n    keys = np.array(seeds[0]["keys"])\n    for s in seeds[1:]:\n        assert list(s["keys"]) == list(keys)\n    return (np.array(seeds[0]["y"]), np.array([person_of(x) for x in seeds[0]["subject"]]),\n            [np.array(s["pred"]) for s in seeds], keys)\n\n\ndef metrics(y, preds, rows):\n    acc = np.mean([accuracy_score(y[rows], p[rows]) for p in preds])\n    qwk = np.mean([cohen_kappa_score(y[rows], p[rows], weights="quadratic") for p in preds])\n    return acc, qwk\n\n\ndef paired(a, b, n_boot=2000, seed=0):\n    ya, sa, pa, ka = load(a)\n    yb, sb, pb, kb = load(b)\n    assert list(ka) == list(kb) and (ya == yb).all()\n    persons = np.unique(sa)\n    rows_of = {p: np.where(sa == p)[0] for p in persons}\n    rng = np.random.default_rng(seed)\n    point = {a: metrics(ya, pa, slice(None)), b: metrics(yb, pb, slice(None))}\n    draws = []\n    for _ in range(n_boot):\n        rows = np.concatenate([rows_of[p] for p in rng.choice(persons, len(persons))])\n        ma, mb = metrics(ya, pa, rows), metrics(yb, pb, rows)\n        draws.append([ma[0], ma[1], mb[0], mb[1], mb[0] - ma[0], mb[1] - ma[1]])\n    d = np.array(draws)\n    ci = lambda c: [round(float(np.percentile(d[:, c], 2.5)), 4), round(float(np.percentile(d[:, c], 97.5)), 4)]\n    return {"persons": len(persons), "windows": int(len(ya)),\n            a: {"acc": round(point[a][0], 4), "acc_ci": ci(0), "qwk": round(point[a][1], 4), "qwk_ci": ci(1)},\n            b: {"acc": round(point[b][0], 4), "acc_ci": ci(2), "qwk": round(point[b][1], 4), "qwk_ci": ci(3)},\n            "diff_acc": round(point[b][0] - point[a][0], 4), "diff_acc_ci": ci(4),\n            "p_acc_le0": float((d[:, 4] <= 0).mean()),\n            "diff_qwk": round(point[b][1] - point[a][1], 4), "diff_qwk_ci": ci(5),\n            "p_qwk_le0": float((d[:, 5] <= 0).mean())}\n\n\ndef explored(run):\n    trials = [t for t in json.load(open(R / run / "study.json"))["trials"] if t.get("value") is not None]\n    out = {}\n    for name in ("face_k", "seq_t"):\n        best = {}\n        for t in trials:\n            v = t["params"].get(name)\n            if v is not None:\n                best.setdefault(v, []).append(t["value"])\n        out[name] = {str(k): {"n": len(v), "best_val": round(max(v), 4)} for k, v in sorted(best.items())}\n    return out\n\n\nif __name__ == "__main__":\n    report = {}\n    for obj in ("acc", "qwk"):\n        a, b = f"dipser_{obj}", f"dipser_rich_{obj}"\n        if not (R / a / "preds_test_seed0.json").exists():\n            print(f"skip {obj}: {a} missing", file=sys.stderr)\n            continue\n        report[obj] = paired(a, b) | {"explored_rich": explored(b)}\n    out = R / "rich_vs_paper.json"\n    out.write_text(json.dumps(report, indent=1))\n    print(json.dumps(report, indent=1))\n', 'analysis_v3/phase7.py': '"""Phase 7 confirmatory analysis (rules pre-declared in context/PLAN_accuracy.md "Phase 7").\n\n1. family: crop_only:<f> vs crop_only:tcheb, paired person bootstrap of pooled out-of-fold\n   QWK over the 57 persons (2000 draws), two-sided p, Holm over 4 families, per run;\n   a family "matters" only if Holm p < 0.05 and CI excludes 0 in BOTH runs (acc, qwk).\n2. crop: crop_only:tcheb vs scene_only (same test).\n3. overall: fixed-split test of dipser_crop vs dipser_rich (13 test persons, 3 seeds).\nWrites results/v6/phase7.json.\n"""\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nfrom sklearn.metrics import accuracy_score, cohen_kappa_score\n\nR = Path(__file__).resolve().parent.parent / "results"\nFAMILIES = ("hahn", "kraw", "kraw_eyes", "kraw_mouth")\nN_BOOT = 2000\n\n\ndef person_of(s):\n    parts = str(s).split("/")\n    return f"{parts[0]}/{parts[2]}" if len(parts) == 3 else str(s)\n\n\ndef q(y, p):\n    return cohen_kappa_score(y, p, weights="quadratic")\n\n\ndef boot_pair(y, persons, pa, pb, seed=0):\n    """b - a: point, 95% CI, two-sided p; pa/pb = lists of prediction arrays (seeds)."""\n    ids = np.unique(persons)\n    rows_of = {i: np.flatnonzero(persons == i) for i in ids}\n    rng = np.random.default_rng(seed)\n    metric = lambda preds, r: (np.mean([q(y[r], p[r]) for p in preds]),\n                               np.mean([accuracy_score(y[r], p[r]) for p in preds]))\n    allr = np.arange(len(y))\n    qa, aa = metric(pa, allr)\n    qb, ab = metric(pb, allr)\n    d = []\n    for _ in range(N_BOOT):\n        r = np.concatenate([rows_of[i] for i in rng.choice(ids, len(ids))])\n        (x1, y1), (x2, y2) = metric(pa, r), metric(pb, r)\n        d.append((x2 - x1, y2 - y1))\n    d = np.array(d)\n    p = float(min(1.0, 2 * min((d[:, 0] <= 0).mean(), (d[:, 0] >= 0).mean())))\n    ci = lambda c: [round(float(np.percentile(d[:, c], 2.5)), 4), round(float(np.percentile(d[:, c], 97.5)), 4)]\n    return {"a_qwk": round(qa, 4), "b_qwk": round(qb, 4), "diff_qwk": round(qb - qa, 4), "ci_qwk": ci(0),\n            "p_qwk": p, "a_acc": round(aa, 4), "b_acc": round(ab, 4), "diff_acc": round(ab - aa, 4),\n            "ci_acc": ci(1), "persons": int(len(ids))}\n\n\ndef holm(ps):\n    order = np.argsort(ps)\n    adj, running = np.empty(len(ps)), 0.0\n    for rank, i in enumerate(order):\n        running = max(running, min(1.0, (len(ps) - rank) * ps[i]))\n        adj[i] = running\n    return adj.tolist()\n\n\ndef main():\n    report = {"family": {}, "crop_vs_scene": {}, "overall_test": {}}\n    for run in ("acc", "qwk"):\n        z = np.load(R / "v4" / f"dipser_crop_{run}" / "family_swap_oof.npz", allow_pickle=True)\n        y, persons = z["y"], z["persons"].astype(str)\n        base = [z["crop_only__tcheb"]]\n        fam = {f: boot_pair(y, persons, base, [z[f"crop_only__{f}"]], seed=i) for i, f in enumerate(FAMILIES)}\n        for f, adj in zip(FAMILIES, holm([fam[f]["p_qwk"] for f in FAMILIES])):\n            fam[f]["p_holm"] = round(adj, 4)\n            fam[f]["matters"] = adj < 0.05 and fam[f]["ci_qwk"][0] > 0\n        report["family"][run] = fam\n        report["crop_vs_scene"][run] = boot_pair(y, persons, [z["scene_only"]], base, seed=9)\n        # 3. fixed-split test vs the rich-feature search (same 13 persons, 3 seeds each)\n        load = lambda d: [json.load(open(R / "v4" / d / f"preds_test_seed{s}.json")) for s in range(3)]\n        a, b = load(f"dipser_rich_{run}"), load(f"dipser_crop_{run}")\n        assert a[0]["keys"] == b[0]["keys"]\n        yt = np.array(a[0]["y"])\n        pt = np.array([person_of(s) for s in a[0]["subject"]])\n        report["overall_test"][run] = boot_pair(yt, pt, [np.array(s["pred"]) for s in a],\n                                                [np.array(s["pred"]) for s in b], seed=11)\n    report["family_matters_in_both_runs"] = {\n        f: bool(report["family"]["acc"][f]["matters"] and report["family"]["qwk"][f]["matters"]) for f in FAMILIES}\n    out = R / "v6" / "phase7.json"\n    out.write_text(json.dumps(report, indent=1))\n    for run in ("acc", "qwk"):\n        print(f"== run {run}")\n        for f in FAMILIES:\n            r = report["family"][run][f]\n            print(f"  {f:10s} vs tcheb: QWK {r[\'a_qwk\']:.3f} -> {r[\'b_qwk\']:.3f}  diff {r[\'diff_qwk\']:+.3f} {r[\'ci_qwk\']} "\n                  f"p {r[\'p_qwk\']:.3f} holm {r[\'p_holm\']:.3f}  acc diff {r[\'diff_acc\']:+.3f}")\n        r = report["crop_vs_scene"][run]\n        print(f"  crop(tcheb) vs scene: QWK {r[\'a_qwk\']:.3f} -> {r[\'b_qwk\']:.3f} diff {r[\'diff_qwk\']:+.3f} {r[\'ci_qwk\']} p {r[\'p_qwk\']:.4f}; "\n              f"acc {r[\'a_acc\']:.3f} -> {r[\'b_acc\']:.3f} {r[\'ci_acc\']}")\n        r = report["overall_test"][run]\n        print(f"  test crop vs rich: QWK {r[\'a_qwk\']:.3f} -> {r[\'b_qwk\']:.3f} {r[\'ci_qwk\']} p {r[\'p_qwk\']:.3f}; "\n              f"acc {r[\'a_acc\']:.3f} -> {r[\'b_acc\']:.3f} diff {r[\'diff_acc\']:+.3f} {r[\'ci_acc\']}")\n    print("family matters in both runs:", report["family_matters_in_both_runs"])\n\n\nif __name__ == "__main__":\n    main()\n', 'kaggle/v4_search/search.py': '"""v4: Bayesian hyper-parameter search (Optuna TPE) on Tchebichef features.\n\nGoal (user, 2026-11-19): the best accuracy reachable with the Tchebichef front-end,\nreported beside QWK, the metric that suits ordinal, imbalanced attention labels.\n\nDATASET  dipser | dipser_rich | dipser_crop | daisee      OBJECTIVE  acc | qwk  (make_kernels.py)\ndipser_crop (Phase 7): adds face_crop, the student\'s face box (the paper "face" stream is the\nwhole webcam frame), with its moment family (Tchebichef / Hahn / Krawtchouk centre, eyes,\nmouth) and order searched; then a family swap: same folds and hyper-parameters, only the\ncrop family changes (family_swap in final.json, out-of-fold predictions in family_swap_oof.npz).\n\nProtocol (no test leakage):\n* DAiSEE: official split. Trials train on Train and are scored on Validation; users that\n  also appear in Validation/Test are removed from training. The best trial is retrained on\n  Train + Validation (fixed epoch count = its best validation epoch, or the same GBM\n  setting) and scores Test ONCE, for 3 seeds.\n* DIPSER: no official split. A fixed person-disjoint, label-stratified split\n  (StratifiedGroupKFold, seed 2026): test = fold 0 (20% of persons), validation = 20% of\n  the remaining persons. Same search / retrain / test-once rule.\n* Population: windows/clips where every stream exists (fixed across trials).\n* Tchebichef orders are searched by SLICING the extracted moments (orthogonal basis:\n  lower orders are the leading coefficients): face spatial order <= 16, temporal <= 6.\n\nSearch space: model {mlp, gbm}; streams (non-empty subset); orders; MLP: hidden, emb,\ndropout, lr, weight decay, batch, head {coral, ce}, class weights {none, sqrt, balanced};\nGBM (LightGBM): trees, leaves, lr, feature fraction, min child, class weights.\nWrites study.json (every trial), final.json (test scores) and preds_test_seed<k>.json.\n"""\nimport json\nimport os\nimport time\nfrom pathlib import Path\n\nimport numpy as np\n\nif "gbm" in os.environ.get("V4_MODELS", "mlp,gbm"):\n    import lightgbm as lgb   # before torch; on macOS torch + lightgbm OpenMP clash (use V4_MODELS=mlp)\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\nDATASET = os.environ.get("V4_DATASET", "dipser")\nOBJECTIVE = os.environ.get("V4_OBJECTIVE", "acc")\nTIMEOUT_S = float(os.environ.get("V4_TIMEOUT_S", str(3.2 * 3600)))\nMAX_TRIALS = int(os.environ.get("V4_MAX_TRIALS", "400"))\nFAST = os.environ.get("V4_FAST", "") == "1"\nMODELS = os.environ.get("V4_MODELS", "mlp,gbm").split(",")   # "mlp" for macOS smoke tests\nON_KAGGLE = os.path.isdir("/kaggle/working")\nOUT = Path("/kaggle/working") if ON_KAGGLE else Path(os.environ.get("V4_OUT", "v4_out"))\nOUT.mkdir(parents=True, exist_ok=True)\nFILES = {"dipser": "corpus_full.npz", "daisee": "daisee_clips_v1.npz",\n         "dipser_rich": "corpus_rich.npz", "dipser_crop": "corpus_rich.npz"}\nSTREAMS = {"dipser": ("face", "facemesh", "head_pose", "physio"),\n           "dipser_rich": ("face", "facemesh", "head_pose", "physio"),\n           "dipser_crop": ("face", "face_crop", "facemesh", "head_pose", "physio"),\n           "daisee": ("face", "facemesh", "head_pose")}[DATASET]\nFACE_K, SEQ_K = 16, 6        # paper orders; overwritten from the data by set_orders()\nVALUES = {"facemesh": 478 * 3, "head_pose": 3, "physio": 8}\nSEQ_OF = {}                  # stream -> temporal order stored in the corpus\nFACE_CHOICES = (4, 6, 8, 12, 16, 20, 24)\n# Phase 7 (dipser_crop): face_crop = the student\'s face box, moments in 5 families\n# (pc_pipeline/moment_families.py), stored at spatial 16 x temporal 8 in corpus_crop.npz.\n# "face" stays the paper stream (the whole webcam frame = the scene).\nCROP_FAMILIES = ("tcheb", "hahn", "kraw", "kraw_eyes", "kraw_mouth")\nCROP_K, CROP_SEQ = 16, 8\nCROP_CHOICES = (4, 6, 8, 12, 16)\nFINAL_SEEDS = (0, 1, 2)\nMAX_EPOCHS = 8 if FAST else 60\nPATIENCE = 8\ntorch.set_num_threads(os.cpu_count() or 4)\nLITERATURE = {"daisee": {"ViBED-Net": 73.43, "Abedi": 67.4, "Safa": 67.32,\n                         "VisioPhysioENet": 63.09}, "dipser": {}, "dipser_rich": {},\n              "dipser_crop": {}}\n\n\n# ----------------------------------------------------------------------------- metrics\ndef qwk(y, p, k):\n    o = np.zeros((k, k))\n    np.add.at(o, (y, p), 1)\n    w = (np.subtract.outer(np.arange(k), np.arange(k)) ** 2) / (k - 1) ** 2\n    e = np.outer(o.sum(1), o.sum(0)) / max(o.sum(), 1)\n    denom = (w * e).sum()\n    return float(1 - (w * o).sum() / denom) if denom > 0 else 0.0\n\n\ndef scores(y, p, k):\n    recall = [float((p[y == c] == c).mean()) if (y == c).any() else None for c in range(k)]\n    present = [r for r in recall if r is not None]\n    return {"acc": float((y == p).mean()), "qwk": qwk(y, p, k),\n            "balanced_acc": float(np.mean(present)), "recall": recall,\n            "pred_dist": np.bincount(p, minlength=k).tolist()}\n\n\n# ----------------------------------------------------------------------------- data\ndef find(name):\n    explicit = os.environ.get("V4_CORPUS")\n    if explicit and Path(explicit).is_file() and Path(explicit).name == name:\n        return Path(explicit)\n    for folder, _, names in os.walk(os.environ.get("V4_INPUT", "/kaggle/input")):\n        if name in names:\n            return Path(folder) / name\n    raise FileNotFoundError(name)\n\n\ndef person_of(s):\n    parts = str(s).split("/")\n    return f"{parts[0]}/{parts[2]}" if len(parts) == 3 else str(s)\n\n\ndef load():\n    d = np.load(find(FILES[DATASET]), allow_pickle=True)\n    c = {k: d[k] for k in d.files}\n    if DATASET == "dipser_crop":\n        crop = np.load(find("corpus_crop.npz"))\n        assert np.array_equal(crop["keys"].astype(str), c["keys"].astype(str)), "crop/rich key order"\n        for f in CROP_FAMILIES:\n            c[f"feat_crop_{f}"] = crop[f"feat_crop_{f}"]\n            assert c[f"feat_crop_{f}"].shape[1] == CROP_K * CROP_K * CROP_SEQ\n        c["face_frac"] = crop["face_frac"]\n        c["avail_face_crop"] = np.ones(len(c["y"]), dtype=bool)   # no face -> zero image\n        c.pop("feat_physio_rich", None)\n    keep = np.ones(len(c["y"]), dtype=bool)\n    for s in STREAMS:\n        keep &= c[f"avail_{s}"].astype(bool)\n    c = {k: (v[keep] if hasattr(v, "__len__") and len(v) == len(keep) else v)\n         for k, v in c.items()}\n    c["y"] = c["y"].astype(np.int64)\n    k = int(c["y"].max()) + 1\n    persons = np.array([person_of(s) for s in c["subjects"].astype(str)])\n    if DATASET == "daisee":\n        split = c["splits"].astype(str)\n        test, val = split == "Test", split == "Validation"\n        train = (split == "Train") & ~np.isin(persons, persons[val | test])\n        trainval_final = (train | val) & ~np.isin(persons, persons[test])\n    else:\n        from sklearn.model_selection import StratifiedGroupKFold\n        idx = np.arange(len(c["y"]))\n        outer = StratifiedGroupKFold(n_splits=5, shuffle=True, random_state=2026)\n        _, test_idx = next(outer.split(idx, c["y"], persons))\n        test = np.isin(idx, test_idx)\n        rest = idx[~test]\n        inner = StratifiedGroupKFold(n_splits=4, shuffle=True, random_state=2026)\n        _, val_part = next(inner.split(rest, c["y"][rest], persons[rest]))\n        val = np.isin(idx, rest[val_part])\n        train = ~test & ~val\n        trainval_final = ~test\n    if FAST:\n        rng = np.random.default_rng(0)\n        for mask in (train, val, test):\n            on = np.flatnonzero(mask)\n            mask[rng.permutation(on)[int(0.15 * len(on)):]] = False\n        trainval_final = train | val\n    c["persons"] = persons\n    return c, k, {"train": train, "val": val, "test": test, "trainval": trainval_final}\n\n\ndef set_orders(c):\n    """Read the stored Tchebichef orders from the feature sizes (paper or rich corpus)."""\n    global FACE_K, SEQ_K\n    for stream, n_values in VALUES.items():\n        if f"feat_{stream}" in c:\n            SEQ_OF[stream] = c[f"feat_{stream}"].shape[1] // n_values\n    SEQ_OF["face"] = SEQ_OF["facemesh"]                  # face shares the video frames\n    if "face_crop" in STREAMS:\n        SEQ_OF["face_crop"] = CROP_SEQ\n    SEQ_K = max(SEQ_OF[s] for s in STREAMS)\n    FACE_K = int(round((c["feat_face"].shape[1] // SEQ_OF["face"]) ** 0.5))\n    assert FACE_K * FACE_K * SEQ_OF["face"] == c["feat_face"].shape[1]\n    print(f"stored orders: face {FACE_K}x{FACE_K}, temporal {SEQ_OF}", flush=True)\n\n\ndef sliced(c, stream, face_k, seq_t, family=None):\n    """Leading coefficients: (values, seq) layout, face values = FACE_K x FACE_K."""\n    if stream == "face_crop":\n        n = len(c["y"])\n        seq_t = min(seq_t, CROP_SEQ)\n        x = c[f"feat_crop_{family}"].reshape(n, CROP_K * CROP_K, CROP_SEQ)[:, :, :seq_t]\n        x = x.reshape(n, CROP_K, CROP_K, seq_t)[:, :face_k, :face_k, :]\n        return np.ascontiguousarray(x.reshape(n, -1), dtype=np.float32)\n    x = c[f"feat_{stream}"]\n    seq = SEQ_OF[stream]\n    seq_t = min(seq_t, seq)\n    face_k = min(face_k, FACE_K)\n    n_values = x.shape[1] // seq\n    x = x.reshape(len(x), n_values, seq)[:, :, :seq_t]\n    if stream == "face":\n        x = x.reshape(len(x), FACE_K, FACE_K, seq_t)[:, :face_k, :face_k, :]\n    return np.ascontiguousarray(x.reshape(len(x), -1), dtype=np.float32)\n\n\n# ----------------------------------------------------------------------------- MLP\nclass Net(nn.Module):\n    def __init__(self, dims, hidden, emb, dropout, k, head):\n        super().__init__()\n        self.towers = nn.ModuleList(\n            nn.Sequential(nn.Linear(d, hidden), nn.GELU(), nn.Dropout(dropout),\n                          nn.Linear(hidden, emb), nn.LayerNorm(emb)) for d in dims)\n        self.drop = nn.Dropout(dropout)\n        out = k - 1 if head == "coral" else k\n        if head == "coral":\n            self.fc = nn.Linear(emb * len(dims), 1, bias=False)\n            self.bias = nn.Parameter(torch.linspace(1, -1, k - 1))\n        else:\n            self.fc = nn.Linear(emb * len(dims), out)\n        self.head, self.k = head, k\n\n    def forward(self, xs):\n        z = self.drop(torch.cat([t(x) for t, x in zip(self.towers, xs)], dim=1))\n        return self.fc(z) + self.bias if self.head == "coral" else self.fc(z)\n\n    def predict(self, logits):\n        if self.head == "coral":\n            return (torch.sigmoid(logits) > 0.5).sum(1)\n        return logits.argmax(1)\n\n\ndef class_weights(y, k, mode):\n    counts = np.bincount(y, minlength=k).astype(float) + 1\n    if mode == "none":\n        w = np.ones(k)\n    elif mode == "sqrt":\n        w = 1 / np.sqrt(counts)\n    else:\n        w = 1 / counts\n    return torch.tensor(w / w.mean() * 1.0, dtype=torch.float32)\n\n\ndef loss_fn(net, logits, y, w):\n    if net.head == "coral":\n        levels = (y[:, None] > torch.arange(net.k - 1)[None, :]).float()\n        per = F.binary_cross_entropy_with_logits(logits, levels, reduction="none").sum(1)\n        return (per * w[y]).mean()\n    return F.cross_entropy(logits, y, weight=w)\n\n\ndef fit_mlp(p, xs_tr, y_tr, xs_ev, y_ev, k, seed, epochs=None):\n    """Train; early-stop on (xs_ev, y_ev) by the OBJECTIVE unless epochs is fixed."""\n    torch.manual_seed(seed)\n    np.random.seed(seed)\n    mean = [x.mean(0, keepdims=True) for x in xs_tr]\n    std = [x.std(0, keepdims=True) + 1e-6 for x in xs_tr]\n    norm = lambda xs: [torch.as_tensor((x - m) / s) for x, m, s in zip(xs, mean, std)]\n    tr, ev = norm(xs_tr), norm(xs_ev)\n    ytr = torch.as_tensor(y_tr)\n    net = Net([x.shape[1] for x in tr], p["hidden"], p["emb"], p["dropout"], k, p["head"])\n    opt = torch.optim.AdamW(net.parameters(), lr=p["lr"], weight_decay=p["wd"])\n    w = class_weights(y_tr, k, p["cw"])\n    best, best_state, best_epoch = -1e9, None, 0\n    for epoch in range(1, (epochs or MAX_EPOCHS) + 1):\n        net.train()\n        order = torch.randperm(len(ytr))\n        for i in range(0, len(order), p["batch"]):\n            b = order[i:i + p["batch"]]\n            opt.zero_grad()\n            loss_fn(net, net([x[b] for x in tr]), ytr[b], w).backward()\n            nn.utils.clip_grad_norm_(net.parameters(), 1.0)\n            opt.step()\n        if epochs is not None:\n            continue\n        net.eval()\n        with torch.no_grad():\n            pred = net.predict(net(ev)).numpy()\n        value = scores(y_ev, pred, k)[OBJECTIVE]\n        if value > best + 1e-9:\n            best, best_epoch = value, epoch\n            best_state = {n: t.clone() for n, t in net.state_dict().items()}\n        if epoch - best_epoch >= PATIENCE:\n            break\n    if best_state is not None:\n        net.load_state_dict(best_state)\n    net.eval()\n    with torch.no_grad():\n        pred = net.predict(net(ev)).numpy()\n    return pred, best_epoch\n\n\n# ----------------------------------------------------------------------------- GBM\ndef fit_gbm(p, x_tr, y_tr, x_ev, k, seed):\n    counts = np.bincount(y_tr, minlength=k).astype(float) + 1\n    w = {"none": np.ones(k), "sqrt": 1 / np.sqrt(counts), "balanced": 1 / counts}[p["cw"]]\n    model = lgb.LGBMClassifier(\n        n_estimators=p["trees"], num_leaves=p["leaves"], learning_rate=p["glr"],\n        colsample_bytree=p["ff"], min_child_samples=p["min_child"], subsample=0.8,\n        subsample_freq=1, reg_lambda=p["l2"], random_state=seed, n_jobs=os.cpu_count(),\n        verbose=-1)\n    model.fit(x_tr, y_tr, sample_weight=(w / w.mean())[y_tr])\n    return model.predict(x_ev).astype(int)\n\n\n# ----------------------------------------------------------------------------- search\ndef features(c, p, rows):\n    xs = [(sliced(c, s, p["crop_k"], p["seq_t"], p["crop_family"]) if s == "face_crop"\n           else sliced(c, s, p["face_k"], p["seq_t"]))[rows] for s in p["streams"]]\n    return xs\n\n\ndef suggest(trial):\n    streams = [s for s in STREAMS if trial.suggest_categorical(f"use_{s}", [True, False])]\n    if not streams:\n        streams = [trial.suggest_categorical("fallback_stream", list(STREAMS))]\n    p = {"streams": streams, "seq_t": trial.suggest_int("seq_t", 1, SEQ_K),\n         "face_k": trial.suggest_categorical("face_k", [k for k in FACE_CHOICES if k <= FACE_K]),\n         "model": trial.suggest_categorical("model", MODELS),\n         "cw": trial.suggest_categorical("cw", ["none", "sqrt", "balanced"])}\n    if "face_crop" in STREAMS:\n        p.update(crop_k=trial.suggest_categorical("crop_k", list(CROP_CHOICES)),\n                 crop_family=trial.suggest_categorical("crop_family", list(CROP_FAMILIES)))\n    if p["model"] == "mlp":\n        p.update(hidden=trial.suggest_categorical("hidden", [64, 128, 256, 512]),\n                 emb=trial.suggest_categorical("emb", [32, 64, 128]),\n                 dropout=trial.suggest_float("dropout", 0.0, 0.5),\n                 lr=trial.suggest_float("lr", 1e-4, 1e-2, log=True),\n                 wd=trial.suggest_float("wd", 1e-6, 1e-1, log=True),\n                 batch=trial.suggest_categorical("batch", [64, 128, 256, 512]),\n                 head=trial.suggest_categorical("head", ["coral", "ce"]))\n    else:\n        p.update(trees=trial.suggest_int("trees", 100, 600, step=50),\n                 leaves=trial.suggest_int("leaves", 8, 64, log=True),\n                 glr=trial.suggest_float("glr", 0.01, 0.2, log=True),\n                 ff=trial.suggest_float("ff", 0.05, 0.5, log=True),\n                 min_child=trial.suggest_int("min_child", 10, 200, log=True),\n                 l2=trial.suggest_float("l2", 1e-3, 10.0, log=True))\n    return p\n\n\ndef main():\n    import optuna\n    start = time.time()\n    c, k, split = load()\n    set_orders(c)\n    y = c["y"]\n    info = {"dataset": DATASET, "objective": OBJECTIVE, "classes": k,\n            "n": {s: int(m.sum()) for s, m in split.items()},\n            "persons": {s: int(len(np.unique(c["persons"][m]))) for s, m in split.items()},\n            "class_dist": {s: np.bincount(y[m], minlength=k).tolist() for s, m in split.items()}}\n    majority = int(np.bincount(y[split["trainval"]], minlength=k).argmax())\n    info["majority_test"] = scores(y[split["test"]], np.full(split["test"].sum(), majority), k)\n    info["literature_acc"] = LITERATURE[DATASET]\n    print(json.dumps(info, indent=1), flush=True)\n    tr, va = np.flatnonzero(split["train"]), np.flatnonzero(split["val"])\n    epochs_of = {}\n\n    def objective(trial):\n        p = suggest(trial)\n        t0 = time.time()\n        xs_tr, xs_va = features(c, p, tr), features(c, p, va)\n        if p["model"] == "mlp":\n            pred, ep = fit_mlp(p, xs_tr, y[tr], xs_va, y[va], k, seed=trial.number)\n            epochs_of[trial.number] = ep\n        else:\n            pred = fit_gbm(p, np.hstack(xs_tr), y[tr], np.hstack(xs_va), k, trial.number)\n        s = scores(y[va], pred, k)\n        for name, value in s.items():\n            trial.set_user_attr(name, value)\n        trial.set_user_attr("seconds", round(time.time() - t0, 1))\n        print(f"trial {trial.number}: {p[\'model\']} {p[\'streams\']} -> val acc {s[\'acc\']:.4f} "\n              f"qwk {s[\'qwk\']:+.4f} ({time.time() - t0:.0f}s)", flush=True)\n        return s[OBJECTIVE]\n\n    study = optuna.create_study(direction="maximize",\n                                sampler=optuna.samplers.TPESampler(seed=2026, n_startup_trials=20))\n    optuna.logging.set_verbosity(optuna.logging.WARNING)\n    study.optimize(objective, n_trials=6 if FAST else MAX_TRIALS,\n                   timeout=None if FAST else TIMEOUT_S, gc_after_trial=True)\n    trials = [{"number": t.number, "value": t.value, "params": t.params, **t.user_attrs}\n              for t in study.trials if t.value is not None]\n    (OUT / "study.json").write_text(json.dumps({"info": info, "trials": trials}, indent=1))\n\n    best = study.best_trial\n    p = suggest(optuna.trial.FixedTrial(best.params))\n    final_rows, te = np.flatnonzero(split["trainval"]), np.flatnonzero(split["test"])\n    xs_f, xs_te = features(c, p, final_rows), features(c, p, te)\n    per_seed = []\n    for seed in FINAL_SEEDS:\n        if p["model"] == "mlp":\n            pred, _ = fit_mlp(p, xs_f, y[final_rows], xs_te, y[te], k, seed,\n                              epochs=max(1, epochs_of.get(best.number, 10)))\n        else:\n            pred = fit_gbm(p, np.hstack(xs_f), y[final_rows], np.hstack(xs_te), k, seed)\n        s = scores(y[te], pred, k)\n        per_seed.append(s)\n        (OUT / f"preds_test_seed{seed}.json").write_text(json.dumps(\n            {"keys": c["keys"][te].astype(str).tolist(), "y": y[te].tolist(),\n             "pred": pred.tolist(), "subject": c["subjects"][te].astype(str).tolist()}))\n        print(f"TEST seed {seed}: acc {s[\'acc\']:.4f} qwk {s[\'qwk\']:+.4f} "\n              f"bal.acc {s[\'balanced_acc\']:.4f} recall {s[\'recall\']}", flush=True)\n    summary = {m: [float(np.mean([s[m] for s in per_seed])), float(np.std([s[m] for s in per_seed]))]\n               for m in ("acc", "qwk", "balanced_acc")}\n    # stable estimate: 5-fold person-grouped CV of the best setting on ALL persons\n    # (fixed epoch count, so no fold early-stops on its own test persons)\n    from sklearn.model_selection import StratifiedGroupKFold\n    everything = np.arange(len(y))\n    folds = list(StratifiedGroupKFold(5, shuffle=True, random_state=0).split(everything, y, c["persons"]))\n    fixed_epochs = max(1, epochs_of.get(best.number, 10))\n\n    def cross_validate(q, label):\n        """5-fold person-grouped CV of setting q; returns (summary, out-of-fold predictions)."""\n        xs_all = features(c, q, everything)\n        oof, rows = np.full(len(y), -1), []\n        for tr_i, te_i in folds:\n            if q["model"] == "mlp":\n                pred, _ = fit_mlp(q, [x[tr_i] for x in xs_all], y[tr_i], [x[te_i] for x in xs_all],\n                                  y[te_i], k, 0, epochs=fixed_epochs)\n            else:\n                pred = fit_gbm(q, np.hstack([x[tr_i] for x in xs_all]), y[tr_i],\n                               np.hstack([x[te_i] for x in xs_all]), k, 0)\n            oof[te_i] = pred\n            rows.append(scores(y[te_i], pred, k))\n        summ = {m: [float(np.mean([r[m] for r in rows])), float(np.std([r[m] for r in rows]))]\n                for m in ("acc", "qwk", "balanced_acc")}\n        summ["recall"] = np.mean([r["recall"] for r in rows], axis=0).round(4).tolist()\n        print(f"CV5 {label}: acc {summ[\'acc\'][0]:.4f} qwk {summ[\'qwk\'][0]:+.4f}", flush=True)\n        return summ, oof\n\n    cv5, _ = cross_validate(p, "best")\n    cv5["majority_acc"] = float(np.mean(y == np.bincount(y).argmax()))\n    family_swap = None\n    if "face_crop" in STREAMS:\n        # Phase 7 question: does the moment family of the face crop matter? Same folds, same\n        # hyper-parameters, only the family (and the stream set) changes; paired by window.\n        family_swap, oof_of = {}, {}\n        runs = [("scene_only", dict(p, streams=["face"]))]\n        for f in CROP_FAMILIES:\n            runs.append((f"crop_only:{f}", dict(p, streams=["face_crop"], crop_family=f)))\n            with_crop = [s for s in STREAMS if s in p["streams"] or s == "face_crop"]\n            runs.append((f"best_with_crop:{f}", dict(p, streams=with_crop, crop_family=f)))\n        for label, q in runs:\n            family_swap[label], oof_of[label] = cross_validate(q, label)\n        np.savez_compressed(OUT / "family_swap_oof.npz", keys=c["keys"].astype(str), y=y,\n                            persons=c["persons"], **{n.replace(":", "__"): v for n, v in oof_of.items()})\n    final = {"info": info, "best_trial": best.number, "best_val": best.value, "cv5": cv5,\n             "best_params": best.params, "final_epochs": epochs_of.get(best.number),\n             "family_swap": family_swap,\n             "n_trials": len(trials), "test_per_seed": per_seed, "test_mean_sd": summary,\n             "wall_s": round(time.time() - start, 1)}\n    (OUT / "final.json").write_text(json.dumps(final, indent=1))\n    print(json.dumps({"test_mean_sd": summary, "cv5": cv5, "majority_test": info["majority_test"]["acc"],\n                      "literature": LITERATURE[DATASET]}, indent=1))\n\n\nif __name__ == "__main__":\n    main()\n', 'analysis_v3/phase8.py': '"""Phase 8 confirmatory analysis (rules pre-declared in context/PLAN_accuracy.md "Phase 8").\n\nInput results/v8/oof.npz (kernel gtao-v8-dipser-time-context): out-of-fold predictions per\narm and seed, same 5 person-grouped folds. Paired person bootstrap (57 persons, 2000 draws)\nof pooled QWK averaged over the 3 seeds; two-sided p.\n1. gru vs none: context "helps" if the 95% CI excludes 0 and p < 0.05.\n2. gru vs ema (1 comparison).\nExploratory: bigru vs none, ema vs none. Writes results/v8/phase8.json.\n"""\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nfrom sklearn.metrics import accuracy_score, cohen_kappa_score\n\nR = Path(__file__).resolve().parent.parent / "results" / "v8"\nN_BOOT = 2000\n\n\ndef metric(y, preds, rows):\n    return (float(np.mean([cohen_kappa_score(y[rows], p[rows], weights="quadratic") for p in preds])),\n            float(np.mean([accuracy_score(y[rows], p[rows]) for p in preds])))\n\n\ndef paired(y, persons, pa, pb, seed):\n    ids = np.unique(persons)\n    rows_of = {i: np.flatnonzero(persons == i) for i in ids}\n    rng = np.random.default_rng(seed)\n    everything = np.arange(len(y))\n    (qa, aa), (qb, ab) = metric(y, pa, everything), metric(y, pb, everything)\n    d = []\n    for _ in range(N_BOOT):\n        r = np.concatenate([rows_of[i] for i in rng.choice(ids, len(ids))])\n        (x1, y1), (x2, y2) = metric(y, pa, r), metric(y, pb, r)\n        d.append((x2 - x1, y2 - y1))\n    d = np.array(d)\n    ci = lambda c: [round(float(np.percentile(d[:, c], 2.5)), 4), round(float(np.percentile(d[:, c], 97.5)), 4)]\n    p = float(min(1.0, 2 * min((d[:, 0] <= 0).mean(), (d[:, 0] >= 0).mean())))\n    return {"a_qwk": round(qa, 4), "b_qwk": round(qb, 4), "diff_qwk": round(qb - qa, 4), "ci_qwk": ci(0),\n            "p_qwk": p, "a_acc": round(aa, 4), "b_acc": round(ab, 4), "diff_acc": round(ab - aa, 4),\n            "ci_acc": ci(1), "persons": int(len(ids))}\n\n\ndef main():\n    z = np.load(R / "oof.npz", allow_pickle=True)\n    y, persons = z["y"], z["persons"].astype(str)\n    arm = lambda a: [z[f"{a}_seed{s}"] for s in range(3)]\n    for a in ("none", "gru", "bigru", "ema"):\n        assert all((p >= 0).all() for p in arm(a)), f"{a}: missing out-of-fold predictions"\n    report = {"gru_vs_none": paired(y, persons, arm("none"), arm("gru"), 0),\n              "gru_vs_ema": paired(y, persons, arm("ema"), arm("gru"), 1),\n              "exploratory_bigru_vs_none": paired(y, persons, arm("none"), arm("bigru"), 2),\n              "exploratory_ema_vs_none": paired(y, persons, arm("none"), arm("ema"), 3)}\n    g = report["gru_vs_none"]\n    report["context_helps"] = bool(g["p_qwk"] < 0.05 and g["ci_qwk"][0] > 0)\n    e = report["gru_vs_ema"]\n    report["gru_beats_ema"] = bool(e["p_qwk"] < 0.05 and e["ci_qwk"][0] > 0)\n    (R / "phase8.json").write_text(json.dumps(report, indent=1))\n    for name, r in report.items():\n        if isinstance(r, dict):\n            print(f"{name:28s} QWK {r[\'a_qwk\']:.3f} -> {r[\'b_qwk\']:.3f} diff {r[\'diff_qwk\']:+.3f} {r[\'ci_qwk\']} "\n                  f"p {r[\'p_qwk\']:.3f} | acc {r[\'a_acc\']:.3f} -> {r[\'b_acc\']:.3f} {r[\'ci_acc\']}")\n    print("context helps:", report["context_helps"], "| gru beats ema:", report["gru_beats_ema"])\n\n\nif __name__ == "__main__":\n    main()\n', 'analysis_v3/phase9.py': '"""Phase 9 confirmatory analysis (rules pre-declared in context/PLAN_accuracy.md "Phase 9").\n\nInput results/v10/oof.npz (kernel gtao-v10-dipser-class-context). Paired person bootstrap\n(57 persons, 2000 draws) of pooled out-of-fold QWK, seeds averaged, two-sided p.\nConfirmatory: leave-one-class-out own_class vs own ("helps" if CI excludes 0 and p < 0.05).\nExploratory: class_only vs own (leave-one-class-out); own_class vs own under person-grouped\n5-fold (1 seed, leak-prone protocol); own under person-grouped vs leave-one-class-out.\nWrites results/v10/phase9.json.\n"""\nimport json\nfrom pathlib import Path\n\nimport numpy as np\n\nfrom phase8 import paired\n\nR = Path(__file__).resolve().parent.parent / "results" / "v10"\n\n\ndef main():\n    z = np.load(R / "oof.npz", allow_pickle=True)\n    y, persons = z["y"], z["persons"].astype(str)\n    runs = lambda name: [z[k] for k in sorted(z.files) if k.rsplit("_seed", 1)[0] == name]\n    for name in ("logo_own", "logo_own_class", "logo_class_only", "pg5_own", "pg5_own_class"):\n        assert runs(name) and all((p >= 0).all() for p in runs(name)), name\n    report = {"own_class_vs_own": paired(y, persons, runs("logo_own"), runs("logo_own_class"), 0),\n              "exploratory_class_only_vs_own": paired(y, persons, runs("logo_own"), runs("logo_class_only"), 1),\n              "exploratory_pg5_own_class_vs_own": paired(y, persons, runs("pg5_own"), runs("pg5_own_class"), 2),\n              "exploratory_own_logo_vs_pg5": paired(y, persons, runs("pg5_own"), runs("logo_own")[:1], 3)}\n    r = report["own_class_vs_own"]\n    report["class_context_helps"] = bool(r["p_qwk"] < 0.05 and r["ci_qwk"][0] > 0)\n    (R / "phase9.json").write_text(json.dumps(report, indent=1))\n    for name, r in report.items():\n        if isinstance(r, dict):\n            print(f"{name:36s} QWK {r[\'a_qwk\']:.3f} -> {r[\'b_qwk\']:.3f} diff {r[\'diff_qwk\']:+.3f} {r[\'ci_qwk\']} "\n                  f"p {r[\'p_qwk\']:.3f} | acc {r[\'a_acc\']:.3f} -> {r[\'b_acc\']:.3f} {r[\'ci_acc\']}")\n    print("class context helps:", report["class_context_helps"])\n\n\nif __name__ == "__main__":\n    main()\n'}
LINKS = [('dataset:corpus_full.npz', 'data/corpus_full.npz'), ('gtao-net-dipser-grid-v2-nested-early-stopping', 'results/v2/raw_dipser'), ('gtao-net-daisee-v2-nested-early-stopping', 'results/v2/raw_daisee'), ('gtao-net-engagenet-v2-nested-early-stopping', 'results/v2/raw_engagenet'), ('gtao-net-dipser-grid-v3-standardised', 'results/v3'), ('gtao-net-dipser-v3b-full-corpus-seed0', 'results/v3b/merged', 'dirs'), ('gtao-net-dipser-v3b-full-corpus-seed1', 'results/v3b/merged', 'dirs'), ('gtao-net-dipser-v3b-full-corpus-seed2', 'results/v3b/merged', 'dirs'), ('gtao-v4-bayes-search-dipser-acc', 'results/v4/dipser_acc'), ('gtao-v4-bayes-search-dipser-qwk', 'results/v4/dipser_qwk'), ('gtao-v4-bayes-search-dipser-rich-acc', 'results/v4/dipser_rich_acc'), ('gtao-v4-bayes-search-dipser-rich-qwk', 'results/v4/dipser_rich_qwk'), ('gtao-v4-bayes-search-dipser-crop-acc', 'results/v4/dipser_crop_acc'), ('gtao-v4-bayes-search-dipser-crop-qwk', 'results/v4/dipser_crop_qwk'), ('gtao-v8-dipser-time-context', 'results/v8'), ('gtao-v10-dipser-class-context', 'results/v10')]
STEPS = [('label_prior', 'analysis_v3', ['label_prior.py', '../data/corpus_full.npz'], {}), ('compare_v3', '.', ['analysis_v3/compare_v3.py', '--gate', '--json', 'results/v3/report.json', '--run', 'v2=results/v2/raw_dipser/gtao_grid_v1', '--run', 'v3 none=results/v3/gtao_grid_v3_none_person_strat', '--run', 'v3 fold=results/v3/gtao_grid_v3_fold_person_strat', '--run', 'v3 subject=results/v3/gtao_grid_v3_subject_person_strat'], {}), ('phase1b', 'analysis_v3', ['phase1b.py', '--corpus', '../data/corpus_full.npz'], {}), ('gate3', 'analysis_v3', ['gate3.py', '--out', '../results/v3b/merged', '--boot', '2000', '--json', '../results/v3b/gate3.json'], {}), ('split_leakage', '.', ['analysis_v3/split_leakage.py'], {'V4_MODELS': 'mlp', 'V4_CORPUS': '__ROOT__/data/corpus_full.npz', 'V4_OUT': '__ROOT__/v4_out'}), ('rich_compare', 'analysis_v3', ['rich_compare.py'], {}), ('phase7', 'analysis_v3', ['phase7.py'], {}), ('phase8', 'analysis_v3', ['phase8.py'], {}), ('phase9', 'analysis_v3', ['phase9.py'], {})]
ON_KAGGLE = os.path.isdir("/kaggle/working")
ROOT = Path("/kaggle/working/code") if ON_KAGGLE else Path("v9_code").resolve()
INPUT = Path(os.environ.get("V9_INPUT", "/kaggle/input"))
SKIP = {"__output__.json", "__results__.html", "__notebook__.ipynb", "custom.css"}

for rel, text in EMBEDDED.items():
    target = ROOT / rel
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text, encoding="utf-8")
    print(f"code {rel}: sha256 {hashlib.sha256(text.encode('utf-8')).hexdigest()[:16]}", flush=True)


def slug_root(slug):
    for folder, dirs, _ in os.walk(INPUT):
        if Path(folder).name == slug:
            return Path(folder)
    return None


def find_file(name):
    for folder, _, names in os.walk(INPUT):
        if name in names:
            return Path(folder) / name
    return None


linked = set()
for source, target, *mode in LINKS:
    if source.startswith("dataset:"):
        path = find_file(source.split(":", 1)[1])
        assert path is not None, f"missing dataset file {source}"
        dest = ROOT / target
        dest.parent.mkdir(parents=True, exist_ok=True)
        os.symlink(path, dest)
        linked.add(dest)
        print(f"input {source} -> {target}", flush=True)
        continue
    root = slug_root(source)
    assert root is not None, f"missing kernel output {source}"
    n = 0
    for folder, _, names in os.walk(root):
        for name in names:
            if name in SKIP or name.endswith(".log"):
                continue
            if mode == ["dirs"] and Path(folder) == root:   # merge: run folders only
                continue
            src = Path(folder) / name
            dest = ROOT / target / src.relative_to(root)
            if dest.exists() or dest.is_symlink():
                raise SystemExit(f"two inputs for one path: {dest}")
            dest.parent.mkdir(parents=True, exist_ok=True)
            os.symlink(src, dest)
            linked.add(dest)
            n += 1
    print(f"input {source} -> {target}: {n} files", flush=True)

for d in ("results/v4", "results/v6", "results/v8", "results/v10"):   # output folders of the steps
    (ROOT / d).mkdir(parents=True, exist_ok=True)
logs = ROOT / "results" / "logs"
logs.mkdir(parents=True, exist_ok=True)
failed = []
for name, cwd, argv, env in STEPS:
    print(f"\n===== {name}: (cd {cwd}) python {' '.join(argv)}", flush=True)
    env = {k: v.replace("__ROOT__", str(ROOT)) for k, v in env.items()}
    run = subprocess.run([sys.executable] + argv, cwd=ROOT / cwd, env={**os.environ, **env},
                         capture_output=True, text=True)
    (logs / f"{name}.txt").write_text(run.stdout)
    print(run.stdout[-4000:], flush=True)
    if run.returncode != 0:
        print(run.stderr[-4000:], flush=True)
        failed.append(name)

out = Path("/kaggle/working/results") if ON_KAGGLE else Path("v9_results").resolve()
for base in ("results", "paper"):
    for p in (ROOT / base).rglob("*"):
        if p.is_file() and not p.is_symlink() and p not in linked:
            dest = out / p.relative_to(ROOT)
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy(p, dest)
            print("wrote", dest.relative_to(out))
if failed:
    raise SystemExit(f"steps failed: {failed}")
